\section{Assumptions}
\begin{assumption}[Smoothness]\label{ass:smooth}
$L$ is $L$‑smooth in the joint variable $z=(x,y)$, i.e.
\[
\|\nabla L(z)-\nabla L(z')\| \le L\|z-z'\|\qquad\forall z,z'\in\mathbb{R}^{n+m}.
\tag{3}
\]
Equivalently,
\[
L(z')\le L(z)+\langle \nabla L(z),z'-z\rangle +\frac{L}{2}\|z'-z\|^{2}.
\tag{4}
\]
\end{assumption}

\begin{assumption}[Bounded Gradient]\label{ass:bounded}
There exists $G>0$ such that for all $t$,
\[
\| \nabla_{x}L(x_t,y_t)\| \le G,\qquad 
\| \nabla_{y}L(x_t,y_t)\| \le G.
\tag{5}
\]
\end{assumption}

\begin{assumption}[Existence of a Stationary Point]\label{ass:stationary}
There exists $(x^{\star},y^{\star})$ satisfying the first‑order optimality (saddle) conditions
\[
\nabla_{x}L(x^{\star},y^{\star})=0,\qquad 
\nabla_{y}L(x^{\star},y^{\star})=0.
\tag{6}
\]
\end{assumption}

The function may be non‑convex in $x$ and non‑concave in $y$; we only require smoothness and boundedness of the gradients.

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\section{Main Convergence Theorem}
\begin{theorem}[Convergence of Simultaneous GDA]\label{thm:main}
Assume \ref{ass:smooth}–\ref{ass:stationary} hold and let the constant step size satisfy
\[
0<\eta\le \frac{1}{L}.
\tag{7}
\]
Define the averaged squared gradient norm
\[
\Phi_T \;:=\; \frac{1}{T}\sum_{t=0}^{T-1}\Bigl\|\nabla_{x}L(x_t,y_t)\Bigr\|^{2}
      +\frac{1}{T}\sum_{t=0}^{T-1}\Bigl\|\nabla_{y}L(x_t,y_t)\Bigr\|^{2}.
\tag{8}
\]
Then for any $T\ge 1$,
\[
\Phi_T \;\le\; \frac{2\bigl(L(z_0)-L^{\star}\bigr)}{\eta T},
\qquad 
L^{\star}:=\inf_{y}\sup_{x}L(x,y).
\tag{9}
\]
Consequently $\Phi_T =\mathcal{O}\!\bigl(1/(\eta T)\bigr)$, i.e. the average gradient norm vanishes at the rate $1/T$.
\end{theorem}

\begin{theorem}[Special Case: Bilinear Games]\label{thm:bilinear}
If $L(x,y)=x^{\top}Ay$ with $A\in\mathbb{R}^{n\times m}$, then the iterates \eqref{eq:update} satisfy
\[
\|(x_T,y_T)-(x^{\star},y^{\star})\| \le (1-\eta^2\sigma_{\min}^2(A))^{T/2}\,\|(x_0,y_0)-(x^{\star},y^{\star})\|,
\]
provided $0<\eta<1/\|A\|_2$. Hence linear convergence is obtained for bilinear games.
\end{theorem}

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\section{Theoretical Properties}
\subsection{Stability}
The bound \eqref{9} shows that the algorithm is \emph{stable} as long as the step size respects $\eta\le 1/L$. Larger steps may cause the quadratic term in the smoothness inequality to dominate, leading to divergence.

\subsection{Hyper‑parameter Sensitivity}
Equation \eqref{9} makes the dependence on $\eta$ explicit:
\[
\Phi_T \propto \frac{1}{\eta T}.
\]
A larger $\eta$ yields a smaller bound per iteration but reduces the admissible range $[0,1/L]$. In practice one often picks $\eta = \frac{c}{\sqrt{T}}$ to obtain the optimal $\mathcal{O}(1/\sqrt{T})$ rate for stochastic variants; for the deterministic setting a constant $\eta$ already gives $\mathcal{O}(1/T)$.

\subsection{Comparison to Baselines}
\begin{itemize}
\item \textbf{Gradient Descent (GD) on $\min_y L(x^{\star},y)$}: obtains $\mathcal{O}(1/T)$ under convexity; GDA recovers the same rate without convexity in $x$.
\item \textbf{Optimistic GDA / Extra‑Gradient}: improve the constant in \eqref{9} and achieve linear rates under a \emph{monotone} (convex‑concave) assumption. Our result is weaker but holds for fully non‑convex–concave problems.
\end{itemize}

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\section{Preliminaries (Definitions and Lemmas)}
\begin{lemma}[Descent Lemma for Smooth Functions]\label{lem:descent}
If $L$ satisfies \eqref{ass:smooth}, then for any $z,z'\in\mathbb{R}^{n+m}$,
\[
L(z')\le L(z)+\langle \nabla L(z),z'-z\rangle+\frac{L}{2}\|z'-z\|^{2}.
\tag{10}
\]
\end{lemma}
\begin{proof}
Directly from the definition of $L$‑smoothness \eqref{ass:smooth}. \hfill\qedsymbol
\end{proof}

\begin{lemma}[Quadratic Upper Bound on the Gradient Mapping]\label{lem:quad}
For the update \eqref{eq:update} with step size $\eta\le 1/L$,
\[
\|G_{t}\|^{2}\;\le\;\frac{2}{\eta}\bigl(L(z_t)-L(z_{t+1})\bigr).
\tag{11}
\]
\end{lemma}
\begin{proof}
Let $z_t=(x_t,y_t)$ and $z_{t+1}=z_t+\eta\,\tilde G_t$ where $\tilde G_t=[\nabla_x L(x_t,y_t);-\nabla_y L(x_t,y_t)] = G_t$. Apply Lemma~\ref{lem:descent} with $z'=z_{t+1}$:
\[
L(z_{t+1})\le L(z_t)+\langle \nabla L(z_t),\eta G_t\rangle+\frac{L}{2}\eta^{2}\|G_t\|^{2}.
\tag{12}
\]
Since $\nabla L(z_t)=G_t$, the inner product equals $\eta\|G_t\|^{2}$. Rearranging,
\[
L(z_t)-L(z_{t+1})\ge \eta\|G_t\|^{2}-\frac{L}{2}\eta^{2}\|G_t\|^{2}
      =\Bigl(\eta-\frac{L\eta^{2}}{2}\Bigr)\|G_t\|^{2}.
\tag{13}
\]
Because $\eta\le 1/L$, we have $\eta-\frac{L\eta^{2}}{2}\ge \frac{\eta}{2}$. Hence,
\[
L(z_t)-L(z_{t+1})\ge \frac{\eta}{2}\|G_t\|^{2}
\;\Longrightarrow\;
\|G_t\|^{2}\le \frac{2}{\eta}\bigl(L(z_t)-L(z_{t+1})\bigr).
\tag{14}
\]
\hfill\qedsymbol
\end{proof}

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\section{Main Proof (Step‑by‑Step Derivation)}
We prove Theorem~\ref{thm:main}. Every non‑trivial manipulation is annotated with a step number.

\subsection*{Step 1 (Apply Lemma~\ref{lem:quad})}
From Lemma~\ref{lem:quad},
\[
\|G_t\|^{2}\;\le\;\frac{2}{\eta}\bigl(L(z_t)-L(z_{t+1})\bigr),\qquad t=0,\dots,T-1.
\tag{15}
\]

\subsection*{Step 2 (Sum over iterations)}
Summing \eqref{15} from $t=0$ to $T-1$ yields
\[
\sum_{t=0}^{T-1}\|G_t\|^{2}
\;\le\;\frac{2}{\eta}\sum_{t=0}^{T-1}\bigl(L(z_t)-L(z_{t+1})\bigr)
      =\frac{2}{\eta}\bigl(L(z_0)-L(z_T)\bigr).
\tag{16}
\]

\subsection*{Step 3 (Lower bound $L(z_T)$ by $L^{\star}$)}
By definition $L^{\star}= \inf_{y}\sup_{x}L(x,y)\le L(z_T)$ for any iterate $z_T$, hence
\[
L(z_0)-L(z_T)\;\le\;L(z_0)-L^{\star}.
\tag{17}
\]

\subsection*{Step 4 (Combine \eqref{16} and \eqref{17})}
Insert \eqref{17} into \eqref{16}:
\[
\sum_{t=0}^{T-1}\|G_t\|^{2}
\;\le\;\frac{2}{\eta}\bigl(L(z_0)-L^{\star}\bigr).
\tag{18}
\]

\subsection*{Step 5 (Relate $\|G_t\|^{2}$ to the two gradient norms)}
Recall $G_t$ is the concatenation of $\nabla_x L$ and $-\nabla_y L$; therefore
\[
\|G_t\|^{2}= \|\nabla_x L(x_t,y_t)\|^{2}+ \|\nabla_y L(x_t,y_t)\|^{2}.
\tag{19}
\]

\subsection*{Step 6 (Divide by $T$ and obtain the average)} 
Dividing \eqref{18} by $T$ and using \eqref{19} gives
\[
\frac{1}{T}\sum_{t=0}^{T-1}\Bigl(\|\nabla_x L(x_t,y_t)\|^{2}
      +\|\nabla_y L(x_t,y_t)\|^{2}\Bigr)
\;\le\;\frac{2}{\eta T}\bigl(L(z_0)-L^{\star}\bigr).
\tag{20}
\]

\subsection*{Step 7 (Identify the left‑hand side as $\Phi_T$)}
By definition \eqref{8}, the left‑hand side of \eqref{20} equals $\Phi_T$, thus we obtain
\[
\Phi_T \;\le\; \frac{2\bigl(L(z_0)-L^{\star}\bigr)}{\eta T}.
\tag{21}
\]

\subsection*{Step 8 (Conclusion)}
Equation \eqref{21} is exactly the bound claimed in \eqref{9}. Hence the theorem holds. \hfill\qedsymbol

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\section{Rate Derivation (With Constants)}
From \eqref{21} we can extract an explicit constant:
\[
C:=2\bigl(L(z_0)-L^{\star}\bigr).
\]
Thus,
\[
\Phi_T\le \frac{C}{\eta T}.
\]
If $L(z_0)-L^{\star}\le D$ for a known $D>0$, then
\[
\Phi_T\le \frac{2D}{\eta T}.
\]
Choosing the largest admissible step $\eta=1/L$ gives the tightest bound
\[
\Phi_T\le \frac{2L\bigl(L(z_0)-L^{\star}\bigr)}{T}.
\]

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\section{Special Cases}
\subsection{Bilinear Games}
The proof of Theorem~\ref{thm:bilinear} follows from the linear dynamics
\[
\begin{bmatrix}x_{t+1}\\ y_{t+1}\end{bmatrix}
=
\underbrace{\begin{bmatrix} I & \eta A\\ -\eta A^{\top} & I\end{bmatrix}}_{M}
\begin{bmatrix}x_{t}\\ y_{t}\end{bmatrix},
\]
whose spectral radius is $\rho(M)=\sqrt{1-\eta^{2}\sigma_{\min}^{2}(A)}<1$ when $0<\eta<1/\|A\|_{2}$. Hence
\[
\bigl\|(x_T,y_T)-(x^{\star},y^{\star})\bigr\|
\le \rho(M)^{T}\,\bigl\|(x_0,y_0)-(x^{\star},y^{\star})\bigr\|,
\]
which yields linear convergence.

\subsection{Strongly‑Monotone Games}
If $L$ is \emph{strongly monotone} in the sense that
\[
\langle G(z)-G(z'),z-z'\rangle\ge \mu\|z-z'\|^{2},\qquad \mu>0,
\]
then a standard contraction argument gives
\[
\|z_{t+1}-z^{\star}\|\le (1-\eta\mu)\|z_{t}-z^{\star}\|,
\]
again leading to a linear rate.

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\section{Discussion}
The deterministic simultaneous GDA enjoys a simple $1/T$ decay of the average squared gradient norm under the minimal smoothness assumption. This matches the optimal rate for first‑order methods applied to non‑convex optimization. The result is agnostic to any convex‑concave structure, making it a robust baseline for min–max learning (e.g., GAN training).  

For stochastic gradients, the same derivation carries through with an additional variance term, producing the classical $\mathcal{O}(1/\sqrt{T})$ bound. More sophisticated variants (extragradient, optimistic updates) improve constants and can achieve linear convergence under monotonicity or bilinearity, as highlighted in Theorems~\ref{thm:bilinear} and the strong‑monotone case.

Future work may explore adaptive step sizes, momentum, or variance reduction while preserving the clean $1/T$ guarantee established above.

